-- Featured picks and parlays: any number per day and tab, listed first on
-- their day on the board. Replaces "rank 1 is the top pick", which allowed
-- exactly one and only on today.
--
-- Generated by drizzle-kit; the two UPDATEs are added by hand so every day
-- that had a top pick keeps it, as a featured one — nothing changes on the
-- board the moment this runs.
ALTER TABLE "parlays" ADD COLUMN "featured" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "picks" ADD COLUMN "featured" boolean DEFAULT false NOT NULL;--> statement-breakpoint
UPDATE "picks" SET "featured" = true WHERE "rank" = 1;--> statement-breakpoint
UPDATE "parlays" SET "featured" = true WHERE "rank" = 1 AND "owner_id" IS NULL;
